SMALLV=[(0, 10.4816), (6553600, 6.37), (13107200, 5.9022), (19660800, 5.6775), (26214400, 5.5628)]

W,H=780,440; L,R,T,B=70,24,24,62
X1=26.2144; Y0,Y1=5,11
def sx(m): return L+m/X1*(W-L-R)
def sy(y): return H-B-(y-Y0)/(Y1-Y0)*(H-T-B)
def svg(th,cat):
    ink,mut,grid,surf=th; c1,c2=cat
    o=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}" font-family="Arial,Helvetica,sans-serif" role="img">']
    o.append(f'<rect width="{W}" height="{H}" fill="{surf}"/>')
    for y in range(5,12):
        o.append(f'<line x1="{L}" x2="{W-R}" y1="{sy(y):.1f}" y2="{sy(y):.1f}" stroke="{grid}" stroke-width="1"/>')
        o.append(f'<text x="{L-8}" y="{sy(y)+4:.1f}" fill="{mut}" font-size="13" text-anchor="end">{y}</text>')
    for m in range(0,27,5):
        o.append(f'<line x1="{sx(m):.1f}" x2="{sx(m):.1f}" y1="{T}" y2="{H-B}" stroke="{grid}" stroke-width="1"/>')
        o.append(f'<text x="{sx(m):.1f}" y="{H-B+20}" fill="{mut}" font-size="13" text-anchor="middle">{m}</text>')
    o.append(f'<text x="{(L+W-R)/2}" y="{H-16}" fill="{ink}" font-size="14" text-anchor="middle">Training tokens (millions); both runs took 4.5 minutes</text>')
    o.append(f'<text transform="translate(20,{(T+H-B)/2}) rotate(-90)" fill="{ink}" font-size="14" text-anchor="middle">Loss</text>')
    o.append(f'<line x1="{L}" x2="{W-R}" y1="{sy(7.59):.1f}" y2="{sy(7.59):.1f}" stroke="{mut}" stroke-width="1.2" stroke-dasharray="2 4"/>')
    o.append(f'<text x="{W-R-6}" y="{sy(7.59)-6:.1f}" fill="{mut}" font-size="13" text-anchor="end">unigram level, 7.59</text>')
    for run,per,c in ((BIG,0.524288,c1),(SMALLB,0.065536,c2)):
        pts=' '.join(f'{sx((i+1)*per):.1f},{sy(v):.1f}' for i,v in enumerate(run))
        o.append(f'<polyline points="{pts}" fill="none" stroke="{c}" stroke-width="2"/>')
    for vs,c in ((BIGV,c1),(SMALLV,c2)):
        for t,v in vs:
            o.append(f'<circle cx="{sx(t/1e6):.1f}" cy="{sy(v):.1f}" r="4.5" fill="{surf}" stroke="{c}" stroke-width="2.2"/>')
    o.append(f'<text x="{sx(X1)-8:.1f}" y="{sy(BIGV[-1][1])-12:.1f}" fill="{ink}" font-size="13" text-anchor="end">val {BIGV[-1][1]:.2f}</text>')
    o.append(f'<text x="{sx(X1)-8:.1f}" y="{sy(SMALLV[-1][1])+22:.1f}" fill="{ink}" font-size="13" text-anchor="end">val {SMALLV[-1][1]:.2f}</text>')
    lx,ly=L+260,T+22
    for i,(c,lab) in enumerate(((c1,'524,288 tokens per step (32 micro-batches), 50 steps'),(c2,'65,536 tokens per step (4 micro-batches), 400 steps'))):
        o.append(f'<line x1="{lx}" x2="{lx+28}" y1="{ly+i*22}" y2="{ly+i*22}" stroke="{c}" stroke-width="2.5"/>')
        o.append(f'<text x="{lx+36}" y="{ly+i*22+4}" fill="{ink}" font-size="13">{lab}</text>')
    o.append(f'<text x="{lx+36}" y="{ly+48}" fill="{mut}" font-size="13">lines: training loss; circles: validation loss</text>')
    o.append('</svg>'); return '\n'.join(o)
light=('#0b1a33','#4a5b78','#dde5f2','#ffffff'); dark=('#e8eefc','#9fb0cf','#22355a','#0b162d')
open(sys.argv[1]+'.svg','w').write(svg(light,('#eb6834','#2a78d6'))); open(sys.argv[1]+'-dark.svg','w').write(svg(dark,('#d95926','#3987e5')))
